h:46px;min-height:36px;padding:0 6px;font-size:12px;font-weight:700;border-radius:10px;border:1px solid var(--line);background:var(--button-paper,var(--paper));color:var(--muted)}\n.more{display:block;width:100%;min-height:44px;margin-top:6px;border-radius:12px;border:2px solid var(--accent);background:var(--button-paper,var(--paper));color:var(--ink);font-size:13px;font-weight:700}\n.h-empty{padding:14px 2px;font-size:13px;color:var(--muted);line-height:1.5}\n\n/* 3x3 : \u6700\u8fd1\u8bb0\u5f55 + 2x2 \u5927\u6309\u94ae */\n.sz-3x3{grid-template-columns:minmax(0,1fr);grid-template-rows:auto minmax(0,1fr);grid-template-areas:\"latest\" \"acts\"}\n.sz-3x3 .lt-day{display:none}\n.sz-3x3 .lt-status{display:none}\n\n/* 6x3 : \u5de6\u4fa7\u6700\u8fd1\u8bb0\u5f55\uff0c\u53f3\u4fa7 2x2 \u5927\u6309\u94ae */\n.sz-6x3{grid-template-columns:minmax(0,1fr) minmax(0,1.2fr);grid-template-rows:minmax(0,1fr);grid-template-areas:\"latest acts\"}\n.sz-6x3 .latest{flex-direction:column;padding:8px}\n.sz-6x3 .lt-name{font-size:17px}\n.sz-6x3 .lt-ico{font-size:20px}\n.sz-6x3 .lt-rel{font-size:12px}\n.sz-6x3 .lt-time{font-size:36px}\n.sz-6x3 .lt-more{font-size:12px}\n.sz-6x3 .lt-nmsg{font-size:16px}\n.sz-6x3 .lt-hint{font-size:12px}\n.sz-6x3 .side{width:auto;height:46px;flex-direction:row;gap:6px;font-size:16px}\n.sz-6x3 .a-top{flex-direction:column;gap:2px}\n.sz-6x3 .a-ico{font-size:26px}\n.sz-6x3 .a-label{font-size:19px}\n.sz-6x3 .a-sub{font-size:12px}\n\n/* 3x6 : \u6700\u8fd1\u8bb0\u5f55\u3001\u8bb0\u5f55\u5217\u8868\u30012x2 \u5927\u6309\u94ae\u7eb5\u5411\u6392\u5217 */\n.sz-3x6{grid-template-columns:minmax(0,1fr);grid-template-rows:auto minmax(0,1fr) 156px;grid-template-areas:\"latest\" \"hist\" \"acts\"}\n.sz-3x6 .lt-time{font-size:30px}\n.sz-3x6 .a-label{font-size:18px}\n.sz-3x6 .a-ico{font-size:22px}\n\n/* 6x6 : \u9876\u90e8\u6700\u8fd1\u8bb0\u5f55\uff0c\u4e0b\u65b9\u5de6\u4fa7\u8bb0\u5f55\u5217\u8868\u3001\u53f3\u4fa7 2x2 \u5927\u6309\u94ae */\n.sz-6x6{grid-template-columns:minmax(0,1fr) minmax(0,1fr);grid-template-rows:auto minmax(0,1fr);grid-template-areas:\"latest latest\" \"hist acts\"}\n.sz-6x6 .latest{padding:10px}\n.sz-6x6 .lt-name{font-size:20px}\n.sz-6x6 .lt-ico{font-size:22px}\n.sz-6x6 .lt-rel{font-size:14px}\n.sz-6x6 .lt-time{font-size:46px}\n.sz-6x6 .lt-day{font-size:15px}\n.sz-6x6 .lt-status{font-size:14px}\n.sz-6x6 .lt-nmsg{font-size:20px}\n.sz-6x6 .lt-hint{font-size:14px}\n.sz-6x6 .side{width:92px;font-size:17px}\n.sz-6x6 .side .s-ico{font-size:24px}\n.sz-6x6 .a-top{flex-direction:column;gap:4px}\n.sz-6x6 .a-ico{font-size:34px}\n.sz-6x6 .a-label{font-size:21px}\n.sz-6x6 .a-sub{font-size:13px}\n\n/* \u5c0f\u5c3a\u5bf8\u4e0b\u7684\u5b8c\u6574\u8bb0\u5f55\u9875 */\n.v-hist{display:flex;flex-direction:column;gap:6px}\n.hv-head{flex:none;display:flex;align-items:center;gap:8px}\n.back{flex:none;min-height:44px;min-width:76px;padding:0 12px;border-radius:14px;border:2px solid var(--accent);background:var(--button-paper,var(--paper));color:var(--ink);font-size:15px;font-weight:800}\n.hv-title{min-width:0;font-size:13px;font-weight:700;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.strip{flex:none;display:flex;align-items:center;gap:6px;padding:4px 6px 4px 10px;min-height:44px;border-radius:12px;background:var(--soft);border:1px solid var(--line)}\n.strip-text{flex:1;min-width:0;font-size:13px;font-weight:700;line-height:1.25}\n.strip-btn{flex:none;min-height:36px;padding:0 12px;border-radius:10px;border:0;background:var(--accent);color:var(--on-accent);font-size:14px;font-weight:800}\n.v-hist .hist{flex:1}\n.sz-6x3.v-hist .hist,.sz-3x3.v-hist .hist{display:block}\n.sz-6x3.v-hist{grid-template-columns:none;grid-template-areas:none}\n";
const TYPES=[
  {id:'feed',label:'喝奶',short:'喝奶',icon:'🍼'},
  {id:'diaper',label:'换尿布',short:'尿布',icon:'🧷'},
  {id:'sleep',label:'入睡',short:'入睡',icon:'🌙'},
  {id:'wake',label:'睡醒',short:'睡醒',icon:'☀️'}
];
const TMAP={feed:TYPES[0],diaper:TYPES[1],sleep:TYPES[2],wake:TYPES[3]};
const NOTICE_MS=8000;
const PAGE=40;

function pad(n){return n<10?'0'+n:String(n)}
function hm(ts){const d=new Date(ts);return pad(d.getHours())+':'+pad(d.getMinutes())}
function dkey(ts){const d=new Date(ts);return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate())}
function dshift(ts,n){const d=new Date(ts);d.setDate(d.getDate()+n);return dkey(d.getTime())}
function dlabel(ts,now){
  const k=dkey(ts);
  if(k===dkey(now))return '今天';
  if(k===dshift(now,-1))return '昨天';
  const d=new Date(ts);
  return (d.getMonth()+1)+'月'+d.getDate()+'日';
}
function durText(ms){
  const m=Math.max(0,Math.floor(ms/60000));
  if(m<1)return '不到1分钟';
  if(m<60)return m+'分钟';
  const h=Math.floor(m/60),r=m%60;
  if(h<24)return r?h+'小时'+r+'分':h+'小时';
  const d=Math.floor(h/24),hh=h%24;
  return hh?d+'天'+hh+'小时':d+'天';
}
function agoText(ts,now){
  const m=Math.floor((now-ts)/60000);
  if(m<1)return '刚刚';
  if(m<60)return m+'分钟前';
  const h=Math.floor(m/60);
  if(h<24)return h+'小时前';
  return Math.floor(h/24)+'天前';
}
function liveStr(mode,ts,t){return mode==='dur'?durText(t-ts):agoText(ts,t)}
function logsOf(s){
  const a=s&&Array.isArray(s.logs)?s.logs:[];
  return a.filter(r=>r&&TMAP[r.type]&&typeof r.ts==='number');
}
function baseLogs(s){return s&&Array.isArray(s.logs)?s.logs:[]}

function mount(ctx){
  const {root,el,state,ui,update,redraw,uid}=ctx;
  const size=ctx.size||root.dataset.size||'3x3';
  const tall=size==='3x6'||size==='6x6';
  const now=Date.now();
  const logs=logsOf(state).sort((a,b)=>b.ts-a.ts);
  const latest=logs[0]||null;
  const live=[];
  const notice=ui.notice&&now-ui.notice.at<NOTICE_MS?ui.notice:null;
  if(!notice)ui.notice=null;

  function fail(){
    ui.flash=null;
    ui.notice={kind:'error',verb:'没有保存成功',text:'请再点一下',at:Date.now()};
    redraw();
  }
  async function add(type){
    const rec={id:uid(),type:type,ts:Date.now()};
    ui.flash={id:rec.id,at:rec.ts};
    ui.notice=null;
    try{
      await update(s=>({...s,logs:[...baseLogs(s),rec]}));
    }catch(e){fail()}
  }
  async function removeRec(rec,verb){
    if(!rec)return;
    const t=TMAP[rec.type];
    ui.notice={kind:'undo',verb:verb,rec:rec,text:t.icon+' '+t.label+' '+hm(rec.ts),at:Date.now()};
    try{
      await update(s=>({...s,logs:baseLogs(s).filter(r=>!(r&&r.id===rec.id))}));
    }catch(e){fail()}
  }
  async function restore(){
    const n=ui.notice;
    if(!n||!n.rec)return;
    const rec=n.rec;
    ui.notice=null;
    ui.flash={id:rec.id,at:Date.now()};
    try{
      await update(s=>{
        const base=baseLogs(s);
        if(base.some(r=>r&&r.id===rec.id))return s;
        return {...s,logs:[...base,rec]};
      });
    }catch(e){fail()}
  }
  function openHist(){ui.view='hist';ui.histTop=0;ui.limit=PAGE;redraw()}
  function closeHist(){ui.view='main';ui.histTop=0;redraw()}

  function liveSpan(cls,ts,mode){
    const n=el('span',{class:cls},liveStr(mode,ts,now));
    live.push({n:n,ts:ts,mode:mode});
    return n;
  }
  function tick(){
    const t=Date.now();
    live.forEach(x=>{x.n.textContent=liveStr(x.mode,x.ts,t)});
    if(ui.notice&&t-ui.notice.at>=NOTICE_MS){ui.notice=null;redraw()}
  }

  function noticeBody(n){
    return [
      el('div',{class:'lt-head'},
        el('span',{class:'lt-ico'},n.kind==='error'?'⚠':'↩'),
        el('span',{class:'lt-name'},n.verb)),
      el('div',{class:'lt-nmsg'},n.text)
    ];
  }
  function emptyBody(){
    return [
      el('div',{class:'lt-head'},
        el('span',{class:'lt-ico'},'👶'),
        el('span',{class:'lt-name'},'还没有记录')),
      el('div',{class:'lt-hint'},'点下面的按钮，记下当前时间')
    ];
  }
  function latestBody(r,withMore){
    const t=TMAP[r.type];
    const today=dkey(r.ts)===dkey(now);
    const row=[];
    if(!today)row.push(el('span',{class:'lt-day'},dlabel(r.ts,now)));
    row.push(el('span',{class:'lt-time'},hm(r.ts)));
    if(withMore)row.push(el('span',{class:'lt-more'},'记录 ›'));
    const out=[
      el('div',{class:'lt-head'},
        el('span',{class:'lt-ico'},t.icon),
        el('span',{class:'lt-name'},t.label),
        liveSpan('lt-rel',r.ts,'ago')),
      el('div',{class:'lt-row'},...row)
    ];
    const s=logs.find(x=>x.type==='sleep'||x.type==='wake');
    if(s){
      out.push(el('div',{class:'lt-status'},
        s.type==='sleep'?'🌙 睡眠中 · 已睡 ':'☀️ 醒着 · 已醒 ',
        liveSpan('dur',s.ts,'dur')));
    }
    return out;
  }


  function latestBlock(){
    const canOpen=!tall&&!!latest;
    const fresh=latest&&ui.flash&&ui.flash.id===latest.id&&now-ui.flash.at<1500;
    let kids;
    if(notice)kids=noticeBody(notice);
    else if(latest)kids=latestBody(latest,canOpen);
    else kids=emptyBody();
    const cls='lt-body'+(fresh&&!notice?' fresh':'');
    const body=canOpen
      ?el('button',{type:'button',class:cls+' lt-open','aria-label':'查看全部记录',onclick:openHist},...kids)
      :el('div',{class:cls},...kids);
    let side;
    if(notice&&notice.kind==='undo'){
      side=el('button',{type:'button',class:'side restore','aria-label':'恢复刚才撤回的记录',onclick:restore},
        el('span',{class:'s-ico'},'↪'),el('span',{},'恢复'));
    }else{
      const a={type:'button',class:'side undo','aria-label':'撤回最近一次记录',onclick:()=>removeRec(latest,'已撤回')};
      if(!latest)a.disabled=true;
      side=el('button',a,el('span',{class:'s-ico'},'↩'),el('span',{},'撤回'));
    }
    return el('div',{class:'latest','aria-live':'polite'},body,side);
  }

  function actionBtn(t){
    const last=logs.find(r=>r.type===t.id);
    const alt=t.id==='sleep'||t.id==='wake';
    return el('button',{type:'button',class:'act'+(alt?' alt':''),'aria-label':'记录'+t.label+'，现在',onclick:()=>add(t.id)},
      el('span',{class:'a-top'},el('span',{class:'a-ico'},t.icon),el('span',{class:'a-label'},t.label)),
      last?liveSpan('a-sub',last.ts,'ago'):el('span',{class:'a-sub'},'未记录'));
  }
  function actions(){
    return el('div',{class:'acts'},...['feed','diaper','sleep','wake'].map(id=>actionBtn(TMAP[id])));
  }

  function histRow(r){
    const t=TMAP[r.type];
    return el('div',{class:'row'},
      el('span',{class:'r-ico'},t.icon),
      el('span',{class:'r-name'},t.label),
      el('span',{class:'r-time'},hm(r.ts)),
      el('button',{type:'button',class:'r-del','aria-label':'删除 '+t.label+' '+hm(r.ts),onclick:()=>removeRec(r,'已删除')},'删除'));
  }
  function histList(){
    const limit=ui.limit||PAGE;
    const counts={};
    logs.forEach(r=>{
      const k=dkey(r.ts);
      const c=counts[k]||(counts[k]={});
      c[r.type]=(c[r.type]||0)+1;
    });
    const kids=[];
    if(!logs.length){
      kids.push(el('div',{class:'h-empty'},'还没有记录。点下面的按钮就会记在这里。'));
    }
    let cur=null;
    logs.slice(0,limit).forEach(r=>{
      const k=dkey(r.ts);
      if(k!==cur){
        cur=k;
        const c=counts[k];
        const txt=TYPES.filter(t=>c[t.id]).map(t=>t.short+c[t.id]).join(' · ');
        kids.push(el('div',{class:'dhead'},el('span',{class:'d-name'},dlabel(r.ts,now)),el('span',{class:'d-cnt'},txt)));
      }
      kids.push(histRow(r));
    });
    if(logs.length>limit){
      kids.push(el('button',{type:'button',class:'more',onclick:()=>{ui.limit=limit+PAGE;redraw()}},
        '显示更早的记录（还有 '+(logs.length-limit)+' 条）'));
    }
    const list=el('div',{class:'hist',onscroll:()=>{ui.histTop=list.scrollTop}},...kids);
    return list;
  }

  let list=null;
  let app;
  if(!tall&&ui.view==='hist'){
    list=histList();
    const parts=[
      el('div',{class:'hv-head'},
        el('button',{type:'button',class:'back','aria-label':'返回',onclick:closeHist},'‹ 返回'),
        el('span',{class:'hv-title'},'全部记录 '+logs.length+' 条'))
    ];
    if(notice){
      const sk=[el('span',{class:'strip-text'},notice.kind==='error'?'⚠ '+notice.verb+'，'+notice.text:'↩ '+notice.verb+' '+notice.text)];
      if(notice.kind==='undo')sk.push(el('button',{type:'button',class:'strip-btn',onclick:restore},'恢复'));
      parts.push(el('div',{class:'strip'},...sk));
    }
    parts.push(list);
    app=el('div',{class:'app v-hist sz-'+size},...parts);
  }else{
    const parts=[latestBlock()];
    if(tall){list=histList();parts.push(list)}
    parts.push(actions());
    app=el('div',{class:'app v-main sz-'+size},...parts);
  }
  root.appendChild(app);
  if(list&&ui.histTop)list.scrollTop=ui.histTop;

  const timer=setInterval(tick,5000);
  return ()=>clearInterval(timer);
}

